<?php
require_once __DIR__.'/common.php';require_staff();
$per=5;$page=page_value();$total=(int)$conn->query('SELECT COUNT(*) FROM phananh_kiennghi')->fetchColumn();$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$off=($page-1)*$per;
$s=$conn->prepare('SELECT * FROM phananh_kiennghi ORDER BY ngaygui DESC,id DESC LIMIT :n OFFSET :o');$s->bindValue(':n',$per,PDO::PARAM_INT);$s->bindValue(':o',$off,PDO::PARAM_INT);$s->execute();$rows=$s->fetchAll();
admin_header('TIẾP NHẬN, XỬ LÝ PHẢN ÁNH - KIẾN NGHỊ');
?><p class="muted">Tổng số: <?=$total?> phản ánh, kiến nghị. Mỗi trang hiển thị <?=$per?> nội dung mới nhất.</p>
<?php if(!$rows):?><div class="panel">Chưa có phản ánh, kiến nghị nào.</div><?php endif;?>
<?php foreach($rows as $r):?><article class="card"><div class="actions" style="justify-content:space-between"><b>Mã tiếp nhận: <?=h($r['ma_tiepnhan'])?></b><span class="status"><?=h($r['trangthai'])?></span></div><h2><?=h($r['tieude'])?></h2><p><b>Người gửi:</b> <?=h($r['hoten'])?> · <b>Điện thoại:</b> <?=h($r['sodienthoai'])?></p><p><b>Địa chỉ:</b> <?=h($r['diachi'])?> · <b>Lĩnh vực:</b> <?=h($r['linhvuc'])?></p><p class="muted">Gửi lúc <?=h($r['ngaygui'])?> · Chế độ: <?=h($r['chedo_hienthi'])?></p><div><?=nl2br(h($r['noidung']))?></div><?php if($r['tep_dinhkem']):?><p><a href="<?=h($r['tep_dinhkem'])?>" target="_blank" rel="noopener">Xem tệp đính kèm</a></p><?php endif;?>
<?php $rep=$conn->prepare('SELECT tr.*,n.hoten FROM traloi_phananh tr LEFT JOIN nguoidung n ON n.id=tr.nguoidung_id WHERE tr.phananh_id=? ORDER BY tr.ngaytraloi DESC');$rep->execute([$r['id']]);$answers=$rep->fetchAll();foreach($answers as $a):?><div class="reply"><b>Trả lời (<?=h($a['ngaytraloi'])?>):</b><p><?=nl2br(h($a['noidung_traloi']))?></p></div><?php endforeach;?>
<form class="reply" method="post" action="traloi.php"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="phananh_id" value="<?=$r['id']?>"><div class="field"><label>Nội dung trả lời / cập nhật xử lý</label><textarea name="noidung_traloi" required placeholder="Nhập nội dung trả lời công dân..."></textarea></div><div class="grid"><div class="field"><label>Cập nhật trạng thái</label><select name="trangthai"><option value="dang_xu_ly">Đang xử lý</option><option value="da_tra_loi">Đã trả lời</option><option value="tu_choi">Từ chối</option><option value="dong">Đã đóng</option></select></div><div class="field"><label>Hiển thị câu trả lời</label><select name="cong_khai"><option value="1">Công khai cho người gửi tra cứu</option><option value="0">Nội bộ</option></select></div></div><button>Gửi trả lời và cập nhật</button></form></article><?php endforeach;?>
<?=pager($total,$per,$page,'phananh_kiennghi.php')?><?php admin_footer();?>
